// Copies the shared fixtures from the iOS repo (the canonical copies) into
// src/lib/__fixtures__/:
//   money-cases.json  generated by SplitSwift/Tools/money-fixtures/generate.py
//   pay-vectors.json  regional payouts (docs/REGIONAL_PAYOUTS_CONTRACT.md); never edit by hand
//   node scripts/sync-money-fixtures.mjs [path/to/SplitSwift]
// Default iOS repo location: ~/Desktop/Projects/Apps/OnlyBills/SplitSwift
import { copyFileSync, readFileSync, existsSync } from 'node:fs';
import { homedir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const iosRepo = process.argv[2] || join(homedir(), 'Desktop/Projects/Apps/OnlyBills/SplitSwift');
const FIXTURES = [
  { name: 'money fixtures', from: 'SplitSwiftTests/Fixtures/Money/money-cases.json', to: 'money-cases.json' },
  { name: 'pay vectors', from: 'SplitSwiftTests/Fixtures/Pay/pay-vectors.json', to: 'pay-vectors.json' },
];

let missing = false;
for (const f of FIXTURES) {
  const source = join(iosRepo, f.from);
  const target = join(here, '../src/lib/__fixtures__', f.to);
  if (!existsSync(source)) {
    console.error(`No ${f.name} at ${source} — pass the SplitSwift repo path.`);
    missing = true;
    continue;
  }
  const before = existsSync(target) ? readFileSync(target, 'utf8') : '';
  copyFileSync(source, target);
  const after = readFileSync(target, 'utf8');
  console.log(before === after ? `${f.name} already in sync` : `${f.name} updated from ${source}`);
}
if (missing) process.exit(1);
